var SZE = 150;
var numX, numY, tiles;

function setup() {
	numX = ~~(windowWidth / SZE);
	numY = ~~(windowHeight / SZE);
	createCanvas(numX * SZE, numY * SZE);
	pixelDensity(1);
	describe("mosaic of quadratic tiles of different patterns from repeating palettes.");


	const palettes = [
		["#8386f5", "#3d43b4", "#04134b", "#083e12", "#1afe49"],
		["#f887ff", "#de004e", "#860029", "#321450", "#29132e"],
		["#e96d5e", "#ff9760", "#ffe69d", "#6a7e6a", "#393f5f"],
		["#ff124f", "#ff00a0", "#fe75fe", "#7a04eb", "#120458"],
		["#ff6e27", "#fbf665", "#73fffe", "#6287f8", "#383e65"],
		["#7700a6", "#fe00fe", "#defe47", "#00b3fe", "#0016ee"],
		["#63345e", "#ac61b9", "#b7c1de", "#0b468c", "#092047"],
		["#af43be", "#fd8090", "#c4ffff", "#08deea", "#1261d1"],
		["#a0ffe3", "#65dc98", "#8d8980", "#575267", "#222035"],
		["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
		["#490109", "#d40011", "#fd7495", "#5e4ef8", "#14029a"],
		["#8f704b", "#daae6d", "#89e3f6", "#4d9e9b", "#44786a"],
		["#fff69f", "#fdd870", "#d0902f", "#a15501", "#351409"],
		["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
		["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"]
	]

	/*
	let subPalletes = shuffle(palettes)
	subPalletes.splice(0, ~~random(subPalletes.length*0.8, subPalletes.length*1));
	*/

	let _palettes = [
		["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
		["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
		["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"]
	]	
	shuffle(palettes, true);
	palettes.splice(0, palettes.length-2);

	tiles = []
	for (let y = 0; y < numY; y++) {
		for (let x = 0; x < numX; x++) {
			// tiles.push(new Tile(x * SZE + SZE / 2, y * SZE + SZE / 2, SZE, random(subPalletes)));
			tiles.push(new Tile(x * SZE + SZE / 2, y * SZE + SZE / 2, SZE, random()<0.1 ? palettes[0]: palettes[1]));
		}
	}

	draw();
}

function draw() {
	background("beige")
	for (const t of tiles) {
		t.show();
	}
	drawVignette();
	// noLoop() removed for animation
}

function drawVignette() {
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)*0.35, 
		width/2, height/2, max(width, height)*0.65
	);

	// Add three color stops
	const clr1 = color("beige");
	clr1.setAlpha(0)
	const clr2 = color("beige");
	clr2.setAlpha(255)
	gradient.addColorStop(0, clr1);
	gradient.addColorStop(1, clr2); // bg

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);
}

function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
		loop();
	}
}



class Tile {
	constructor(x, y, s, p) {
		this.x = x;
		this.y = y;
		this.s = s;
		this.p = p.map((c) => c + "80");

		this.layers = shuffle(["draw1", "draw2", "draw3", "draw4", "draw5", "draw6", "draw7", "draw8", "draw9"]);
		if (random()<0.5) this.layers.splice(0, ~~random(this.layers.length*0.1, this.layers.length*0.9))
	}

	show() {
		push();
		rectModestrokeWeight(this.s * 0.01)
		translate(this.x, this.y);

		for (let l of this.layers) {
			this.randAttrs();
			eval("this." + l + "()");
		}

		pop();
	}

	randAttrs() {
		noFill()
		noStroke();
		if (random() < 0.5) {
			fill(random(this.p));
		} else {
			drawingContext.setLineDash([]);
			if (random()<0.5) drawingContext.setLineDash(this.randArr());
			stroke(random(this.p));
		}
		const sw = random(this.s * 0.01, this.s * 0.05)
		strokeWeight(sw);
		// blendMode(random([BLEND, ADD, MULTIPLY, DIFFERENCE]))
	}

	draw1() {
		const s = random(this.s * 0.5, this.s)
		if (random() < 0.5) {
			circle(0, 0, s);
		} else {
			rect(0, 0, s, s)
		}
	}

	draw2() {
		const pad = this.s * 0.1;
		for (let s = pad; s < 10 * pad; s += pad) {
			if (random() < 0.5) {
				rect(0, 0, s, pad);
			} else {
				rect(0, 0, pad, s);
			}
		}
	}

	draw3() {
		const s2 = this.s * 0.5;
		line(-s2, -s2, s2, s2);
		line(s2, -s2, -s2, s2);
	}
	draw4() {
		var s2 = this.s * 0.5;
		line(-s2, 0, s2, 0);
		line(0, -s2, 0, s2);
	}

	draw5() {
		var s2 = this.s / 2;
		const num = ~~random(3, 7);
		for (let i = 0; i < 1; i++) {
			const x1 = this.rndRange(s2)
			const y1 = this.rndRange(s2)
			const x2 = this.rndRange(s2)
			const y2 = this.rndRange(s2)
			const x3 = this.rndRange(s2)
			const y3 = this.rndRange(s2)
			triangle(x1, y1, x2, y2, x3, y3)
			triangle(-x1, y1, -x2, y2, -x3, y3)
			triangle(x1, -y1, x2, -y2, x3, -y3)
			triangle(-x1, -y1, -x2, -y2, -x3, -y3)
		}
	}

	draw6() {
		var s2 = this.s / 2;
		var num = ~~random(3, 11);
		beginShape();
		for (let i = 0; i < num; i++) {
			const a = TWO_PI * i / num;
			const x = cos(a) * s2;
			const y = sin(a) * s2;
			vertex(x, y)
		}
		endShape(CLOSE)
	}

	draw7() {
		var s2 = this.s / 2;
		var num = ~~random(3, 11);
		push()
		for (let i = 0; i < num; i++) {
			ellipse(0, 0, this.s, s2)
			rotate(TWO_PI / num)
		}
		pop()
	}

	draw8() {
		var s2 = this.s / 2;
		var num = ~~random(1, 6);
		var sw = s2/num;
		push()
		strokeWeight(sw)
		translate(sw/2, sw/2)
		for (let j = -num; j < num; j++) {
			for (let i = -num; i < num; i++) {
				point(i*sw, j*sw)
			}
		}
		pop()
	}


	draw9() {
		const r = this.s / 4 - this.rndRange(this.s / 8);
		var num = ~~random(3, 11);
		for (let i = 0; i < num; i++) {
			var a = TWO_PI * i / num;
			var x = cos(a) * r;
			var y = sin(a) * r;
			push()
			translate(x, y)
			rotate(a+HALF_PI)
			line(-this.s / 8, 0, this.s / 8, 0)
			pop()
		}
	}

	rndRange(d) {
		return random(-d, d);
	}

	randArr() {
		let arr = [];
		var num = random(1, 10);
		for (let i = 0; i < num; i++) {
			arr.push(~~random(this.s*0.06, this.s*0.3))
		}
		return arr;
	}
}
